INSERT INTO "public"."schedules" ("id", "title", "date", "preacher", "bibleVerse", "description", "leader", "musician", "multimedia", "accommodation", "cookingGroup", "cleaningGroup", "type", "noteWriter", "createdAt", "updatedAt") VALUES
	(5, 'What is the church? - Holiness', '2023-09-08 18:00:00+00', 'Pdt. Titus Christanto', '1 Korintus 1 -2, 5, dan 6', 'What is the Church? Is it relevant for us as fellowship members? In this series, we begin by really learning what a church actually is, and what is actually desired for the people in it.', 'Reggy Irawan', 'Felix Arjuna', 'Victor Jordan', 'Jordie Yonathan', 'Group 6', 'Group 2', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(7, 'What is the church? - Loving', '2023-09-22 20:00:00+00', 'Pdt. Titus Christanto', '1 Korintus 8-14, 8:1', 'The law of love is something we hear all the time and sometimes it becomes a clichÃ©. However, sometimes the simple things become the most difficult things for us to apply. Many churches become places where people get hurt, become wounded and even outcast, not to bring out the love of Christ there. ', 'Toni Setiawan', 'Clarissa Adelyne', 'Danny Kurniawan', 'Reggy Irawan', 'Group 1', 'Group 5', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(12, 'Evangelism', '2023-10-27 20:00:00+00', 'Ev. Nehemiah Riggruben', 'Matius 28:19-20', 'A proper understanding of the Bible and the practice of evangelism is one of the signs of a healthy Church. Sometimes we misinterpret what Evangelism is, Evangelism:
1. It is not imposing our beliefs on others (1 Corinthians 3:6).
2. It is not Personal Testimonies (can be part of evangelism, but must contain the gospel)
3. Not Social Action (Social action without evangelism only leads to humanism)
4. It is not Apologetics (Apologetics is giving an account of the Christian faith to those who question it. It is defensive, whereas Evangelism is an action to tell the good news)
5. Not result oriented (Evangelism must be based on a biblical understanding of repentance, some people just don''t respond to the gospel, Result oriented can turn a healthy church into a business, Result oriented produces Christians who feel guilty)', 'Albertus Pandya', 'Clarissa Adelyne', 'Reggy Irawan', 'Jansen Nathanel', 'Group 2', 'Group 3', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(51, 'Exposition: Book of Romans', '2024-07-12 22:00:00+00', 'Pdt. John Kusuma', 'Romans 9:1-16', 'Basic Principles of Faith: Exposition on Romans 9:1-16', 'Oliver Renaldi', 'Clarissa Adelyne', 'Danny Kurniawan', 'Reggy Irawan', 'Group 2', 'Group 3', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(53, 'Exposition: Book of Romans (Perjamuan Kudus)', '2024-07-26 22:00:00+00', 'Pdt. Titus Christanto', 'Romans 9:30-33 & Romans 10:1-3', 'Basic Principles of Faith: Exposition on Romans 9:30-33 & Romans 10:1-3', 'Winston A.', 'Wynnona A.', 'Victor Jordan', 'Oliver Renaldi', 'Group 5', 'Group 6', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(10, 'Expositional Preaching', '2023-10-13 20:00:00+00', 'Pdt. Titus Christanto', '2 Timotius 4 : 2', 'We often hear the term expositional preaching, and this is one of the preaching principles also applied in PERKI. As a non-denominational fellowship, do we really understand what expositional preaching is and why it is included in the Church health indicators?
', 'Danny Kurniawan', 'Reggy Irawan', 'Arya Wisnu', 'Oliver Renaldi', 'Group 3', 'Group 4', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(24, 'Corporate Prayer', '2024-01-19 23:00:00+00', 'Billy Lugito', 'Matius 6:9-13, Roma 12:12', 'Prayer is the breath of a believer''s life, perhaps a term we are familiar with. Considering how important the effect of prayer is for believers, the church is expected to invite the congregation to pray communally by following the way Jesus Christ taught about prayer in Matthew 6:9-13.

In this theme presentation, we will explain the specific meaning of the words (the use of the word Father, Amen) in prayer in Matthew 6:9-13 and several types of prayers that can build a local church in Matthew 6:9-13 sequentially.
', '', 'Felix Arjuna', NULL, NULL, NULL, 'Group 6', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(35, 'BCP Week', '2024-03-29 23:00:00+00', 'Oliver Renaldi', '--', 'Coming soon.', '', 'Felix Arjuna', NULL, NULL, NULL, 'Group 3', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(14, 'Membership', '2023-11-10 22:00:00+00', 'Pdt. Titus Christanto', 'Kisah Para Rasul 2:41-47, 1 Korintus 12:12-31', 'God commands us to commit to membership in the local church.
What does the Bible say about membership? 
As a follower of Christ, membership in a local church is an absolute requirement in fulfilling our obligations towards fellow believers. There are many descriptions of the church in the Bible, such as: the church as a family in Christ (1Tim 5), the church as members of the body of Christ (1Cor 12:21-26), the church as a nation following God, etc. Through these metaphors we can see what callings we have to fulfill as a member of the church. 
1. We are called to rebuke one another as brothers and sisters (1Tim 5:1-2) / as family in Christ
2. Submit to leaders and each other (Heb 13:17, Eph 5:19-21) / the church as a nation
3. Live out each other''s roles as members of the body of Christ, and thus be a support to the other members of the body (1 Cor 12:21-26, Eph 4:15-16) / the church as members of the body of Christ.

B. Why is it important for us to fulfill this role?
1. Fulfilling this calling (3 points above) = obeying God''s commands written in the bible 
2. Anti-institutional sentimentality has the potential to divide Christianity. There is no way we can fulfill our role as members of the body of Christ if we are not rooted in Christ in a church. 
3. Without membership commitment from its members, the church will not be able to exercise its authority to: baptize people in the name of Christ, rebuke/discipline/even excommunicate its members (important to discuss the context of why discipline is necessary in a church! 1Cor 5, Acts 5:1-11), etc.
4. Without self-commitment from its members, the church will not be able to fulfill its calling as one body of Christ. ', 'Reggy Irawan', 'Jordie Yonathan', 'Danny Kurniawan', 'Jordie Yonathan', 'Group 5', 'Group 1', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(29, 'Exposition - Book of Romans', '2024-02-23 23:00:00+00', 'Pdt. Titus Christanto', 'Roma 1:1-7', 'Basic Principles of Faith: Exposition on Romans 1:1-7', 'Albertus Pandya', 'Felix Arjuna', 'Victor Jordan', 'Danny Kurniawan', 'Group 1', 'Group 2', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(44, 'Exposition: Book of Romans', '2024-05-24 22:00:00+00', 'Pdt. John Kusuma', 'Roma 6:1-14', 'Exposition on the Book of Romans.', 'Reggy Irawan', 'Wynnona A.', 'Danny Kurniawan', NULL, 'Group 4', 'Group 2', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(31, 'Beware of Sin!', '2024-03-08 21:00:00+00', 'Ev. Nehemiah Riggruben', 'Roma 1:18-32', 'Basic Principles of Faith: Exposition on Romans 1:18-32', 'Winston A.', 'Oliver Renaldi', 'Felix Arjuna', 'Albertus Pandya', 'Group 2', 'Group 3', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(16, 'Discipleship and Growth', '2023-11-24 22:00:00+00', 'Pdt. John Kusuma', 'Yohanes 21:14-22, Matius 4:19-20', 'What is discipleship? Is discipleship in a church important? Why is discipleship in the church important and what exactly is the purpose of discipleship? Who is responsible for discipleship? 

Discipleship is a command given directly by Jesus through the great commission in Matthew 28:19-20 to His disciples, including us believers. Through this series, we will get to know more about what discipleship is, why in a healthy church discipleship must exist, and how growth in a healthy church can be seen through discipleship.

Perhaps as a relevance for us in a fellowship and not a church, it is worth mentioning that discipleship in the community is important too and does not apply only in the church, although in the larger context we are talking about the marks of a healthy church.', 'Toni Setiawan', 'Danny Kurniawan', 'Victor Jordan', 'Reggy Irawan', 'Group 1', 'Group 6', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(23, 'Leadership', '2024-01-12 23:00:00+00', 'Pdt. Titus Christanto', 'Ibr. 13:7, Mat. 18:15-20, Kis. 6:1-7 ', 'What does the church leadership structure look like? What are elders, assemblies, and deacons? What are their duties? What are the requirements for their appointment? 

In this theme, we will discuss the church leaders of the early church consisting of assemblies, elders, and deacons. This theme aims to help the congregation understand the duties of the church administrators and participate in the submission and participation of church policies.', 'Winston Alexander', 'Wynnona Angelica', 'Danny Kurniawan', 'Oliver Renaldi', 'Group 3', 'Group 1', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(25, 'The Great Commission', '2024-01-26 23:00:00+00', 'Pdt. John Kusuma', 'Matius 28:19-20', 'We may have heard of the great commission that Jesus gave in Matthew 28:19-20, but through this topic we are taught to know more about what the great commission actually is. 

Who is this great commission for and who should carry it out? 
What exactly is the big picture of the great commission that the Lord Jesus wants to convey? 
What did Jesus already do in the Great Commission? 
What did Jesus'' disciples understand about this commission and what did they do? 
What is the main/great purpose of the great commission that Jesus delivered?', 'Albertus Pandya', 'Reggy Irawan', 'Felix Arjuna', 'Danny Kurniawan', 'Group 6', 'Group 5', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(27, 'Raising up leaders', '2024-02-09 23:00:00+00', 'Pdt. John Kusuma', 'Markus 10:25, 2 Timotius 2:2', 'The faith once delivered to the saints must be passed on from generation to generation to generation. In this chapter we will look at nine signs to identify, grow, and train leaders for a healthy church. Critical points are: the concern to spread the gospel both geographically (missions) and generationally and nine marks that are helpful to identifying, growing and training elders.', 'Toni Setiawan', 'Clarissa Adelyne', 'Arya Wisnu', 'Oliver Renaldi', 'Group 4', 'Group 5', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(19, 'Christmas service - J.E.S.U.S ', '2023-12-15 23:00:00+00', 'Pdt. Titus Christanto', '1 Timotius 1:15-17', 'Let''s come to our christmas service and celebrate christmas together. ', 'Reggy Irawan', 'Danny Kurniawan', 'Arya Wisnu', 'Jordie Yonathan', 'Group 1', 'Group 1', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(4, 'Sent to show Christ''s Glory', '2023-07-28 20:00:00+00', 'Pdt. Titus Christanto', 'Yohanes 12:27-36', 'According to the Bible, there is nothing greater than the glory of God. But that term is so far away for us now. Most Christians have heard of doing things for the glory of God, but what does that mean? 

Do you want to have meaning in life? Do you have a need for deep personal change? Do you care about justice in the world? The key to all of those things is the glory of God.
', 'Danny Kurniawan', 'Reggy Irawan', 'Danny Kurniawan', 'Danny Kurniawan', 'Group 6', 'Group 2', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(33, 'Kemunafikan', '2024-03-22 21:00:00+00', 'Pdt. John Kusuma', 'Roma 2:17-29', 'Basic Principles of Faith: Exposition on Romans 2:17-29', 'Danny Kurniawan', 'Wynnona A.', 'Reggy Irawan', 'Reggy Irawan', 'Group 5', 'Group 6', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(38, 'Bergantung Pada Kasih Karunia', '2024-04-12 22:00:00+00', 'Pdt. Titus Christanto', 'Roma 3:9-20', 'Basic Principles of Faith: Exposition on Romans 3:9-20', 'Albertus Pandya', 'Felix Arjuna', 'Arya Wisnu', NULL, 'Group 6', 'Group 2', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(40, 'Memaknai Anugerah dalam Iman dan Pembenaran', '2024-04-26 22:00:00+00', 'Ev. Nehemiah Riggruben', 'Roma 4:1-12', 'Basic Principles of Faith: Exposition on Romans 4:1-12', 'Toni Setiawan', 'Clarissa Adelyne', 'Felix Arjuna', 'Danny Kurniawan', 'Group 3', 'Group 4', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(42, 'Exposition: Book of Romans', '2024-05-10 22:00:00+00', 'Ev. Nehemiah Riggruben', 'Roma 5:1-11', 'Exposition on the Book of Romans.', 'Winston A.', 'Danny Kurniawan', 'Victor Jordan', NULL, 'Group 1', 'Group 6', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(46, 'Exposition: Book of Romans', '2024-06-07 22:00:00+00', 'Pdt. Titus Christanto', 'Romans 7:1-12', 'Basic Principles of Faith: Exposition on Romans 7:1-12', 'Steffen Josua', 'Clarissa Adelyne', 'Reggy Irawan', NULL, 'Group 6', 'Group 4', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(48, 'Exposition: Book of Romans', '2024-06-21 22:00:00+00', 'Ev. Nehemiah Riggruben', 'Romans 8:1-17', 'Basic Principles of Faith: Exposition on Romans 8:1-17', 'Toni Setiawan', 'Oliver Renaldi', 'Arya Wisnu', 'Danny Kurniawan', 'Group 3', 'Group 6', 'church_service', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(15, 'Discipline', '2023-11-24 23:00:00+00', 'Ev. Nehemiah Riggruben', 'Matius 18:15-20, 1 Korintus 5', 'Church discipline is not uncommon, both in our fellowship and beyond. Basically, church discipline is the action of the church in confronting someone''s sin and admonishing them to repent, which if not repented of, could lead to the removal of that person from church membership. In a broader sense, church discipline is everything the church does to help its members pursue holiness and resist sin.

- Etymologically, discipline and disciple are two related words. Both have to do with teaching and correction. Therefore, the church recognizes 2 forms of discipline: formative discipline and corrective discipline. These two are inseparable in our process of evangelizing/discipling others.

- Practicing church discipline is Jesus'' command in Matthew 18:15-20. Unrepented sin has the opportunity to bring destruction in the church. (May discuss the context of the ancient church, excommunication, etc.)

- Church discipline is a form of love. Just as the Father disciplines those who disobey Him (Heb 12:8), we must also have enough love to discipline those who begin to stray from church life due to certain sins. Moreover, church discipline is not only for the benefit of the church, but even more so for the salvation of the person. And everything is for the glory of God. ', 'Albertus Pandya', 'Danny Kurniawan', 'Arya Wisnu', 'Reggy Irawan', 'Group 5', 'Group 3', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(21, 'New Year Eve', '2023-12-29 23:00:00+00', 'Danny Kurniawan', 'Coming soon', 'Little summary to our new year eve event.', 'Danny Kurniawan', 'Felix Arjuna', NULL, NULL, NULL, 'Group 3', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(17, '1. Advent Theme', '2023-12-01 23:00:00+00', 'Billy Lugito', 'Lukas 2:8-20', '1. Advent Theme', '', 'Albertus Pandya', NULL, NULL, NULL, 'Group 6', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(49, 'Exposition: Book of Romans', '2024-06-28 22:00:00+00', 'Steffen Josua', 'Romans 8:18-30', 'Basic Principles of Faith: Exposition on Romans 8:18-30', 'Reggy Irawan', 'Felix Arjuna', NULL, NULL, NULL, 'Group 1', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(6, 'What is the church? - Unity', '2023-09-15 20:00:00+00', 'Danny Kurniawan', '1 Korintus 3:1-9, 11:17-34', 'What exactly does unity in the Church mean? What does it mean to be a Church where all members must be in harmony with each other? What does the Bible mean by one Church?', '', 'Albertus Pandya', NULL, NULL, NULL, 'Group 4', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(8, 'Biblical Theology', '2023-09-29 20:00:00+00', 'Steffen Josua', 'Lukas 24:13-35', 'Biblical theology teaches us to read the Bible as one story about the person and work of Christ. Biblical theology is not only central to how we should read the Bible, but it is also central to a healthy church. It is important not to just take a verse for a particular topic but to see the Bible as a whole.', '', 'Danny Kurniawan', NULL, NULL, NULL, 'Group 6', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(9, 'The Gospel', '2023-10-06 20:00:00+00', 'Billy Lugito', 'Roma 10:9, 17', 'The gospel is the center of Scripture, the center of our faith, and the center of every healthy church. Gospel-centeredness is the cure for the internal challenges that the church faces. Be careful also with the false gospel, where it seems that we have centered on the gospel but in fact it is the wrong gospel. Have we as a fellowship done this point well?', '', 'Albertus Pandya', NULL, NULL, NULL, 'Group 1', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(11, 'Conversion', '2023-10-20 18:00:00+00', 'Oliver Renaldi', 'Kisah Para Rasul 20:21', 'One of the signs of a healthy Church is characterized by the conversion of its members from a proper understanding of the Gospel. In today''s worldview that is:
1. Skeptical that change/repentance is possible
2. That our nature or personality cannot be changed
3. A sign of maturity is accepting ourselves as we are, etc.
Therefore we will look at the Truth about repentance in the Bible
', '', 'Danny Kurniawan', NULL, NULL, NULL, 'Group 2', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(82, 'Advent Week 1', '2024-11-22 23:00:00+00', '', 'Luke 2:8-20', 'Advent: Hope', 'Reggy Irawan', 'Felix Arjuna', '-', '-', '-', 'Group 5', 'bible_study', 'Kezia Singgih', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(83, 'Advent Week 2', '2024-11-29 23:00:00+00', 'Pdt. John Kusuma', 'Isaiah 40:1-11', 'Kemuliaan Allah, Penghiburan Kita', 'Danny Kurniawan', 'Oliver Renaldi', 'Arya Wisnu', 'Danny Kurniawan', 'Group 2', 'Group 6', 'church_service', 'Victor Jordan', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(84, 'Advent Week 3', '2024-12-06 23:00:00+00', '', 'Yohanes 3:16', 'Advent: Joy', 'Steffen Tjandra', 'Clarissa Adelyne', '-', '-', '-', 'Group 1', 'bible_study', 'Tius Theodore', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(85, 'Advent Week 4', '2024-12-13 23:00:00+00', '', 'Matius 2', 'Advent: Love', 'Victor Jordan', 'Danny Kurniawan', '-', '-', '-', 'Group 2', 'bible_study', 'Ruth Siahaan', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(13, 'Evangelism - Part 2', '2023-11-03 21:00:00+00', 'Steffen Josua', 'Matius 28:19-20', 'Biblical understanding and evangelistic practices are essential for church health
a. A healthy church is rooted in God-centered messages and motives.
b. Healthy churches want to end false evangelism.
c. Healthy churches are committed to sharing a living and dynamic gospel.
d. Healthy churches understand that God is at work in the gospel.

Reflections
a. Is our evangelism motivation correct?
b. Do you have the compassion to evangelize someone?
c. What prevents me from evangelizing?
d.  What should I do to evangelize someone?
e. How can I evangelize without being offensive or patronizing?

', '', 'Felix Arjuna', NULL, NULL, NULL, 'Group 5', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(30, 'Kuasa Injil untuk keselamatan dan Perubahan', '2024-03-01 23:00:00+00', 'Steffen Josua', 'Roma 1:8-17', 'Basic Principles of Faith: Exposition on Romans 1:8-17', '', 'Felix Arjuna', NULL, NULL, 'Group 1', 'Group 1', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(20, 'Christmas Eve', '2023-12-22 23:00:00+00', 'Oliver Renaldi', 'Coming soon', 'Little summary to our christmas eve event.', '', 'Danny Kurniawan', NULL, NULL, NULL, 'Group 4', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(18, '2. Advent Theme', '2023-12-08 23:00:00+00', 'Steffen Josua', 'Coming soon', '2. Advent theme', '', 'Clarissa Adelyne', NULL, NULL, NULL, 'Group 5', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(32, 'The Righteousness of God', '2024-03-15 23:00:00+00', 'Oliver Renaldi', 'Roma 2:1-16', 'Basic Principles of Faith: Exposition on Romans 2:1-16', '', 'Felix Arjuna', NULL, NULL, NULL, 'Group 4', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(22, 'Discipleship and Growth', '2024-01-06 23:00:00+00', 'Oliver Renaldi', 'Yohanes 21:14-22, Matius 4:19-20', 'What is discipleship? Is discipleship in a church important? Why is discipleship in the church important and what exactly is the purpose of discipleship? Who is responsible for discipleship? 

Discipleship is a command given directly by Jesus through the great commission in Matthew 28:19-20 to His disciples, including us believers. Through this series, we will get to know more about what discipleship is, why in a healthy church discipleship must exist, and how growth in a healthy church can be seen through discipleship.

Perhaps as a relevance for us in a fellowship and not a church, it is worth mentioning that discipleship in the community is important too and does not apply only in the church, although in the larger context we are talking about the marks of a healthy church.
', '', 'Clarissa Adelyne', NULL, NULL, NULL, 'Group 2', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(26, 'Missions', '2024-02-02 23:00:00+00', 'Billy Lugito', 'Kisah Para Rasul 1:8', 'Mission is a critical point of the entire story of the bible. The salvation of Jesus Christ leads to a mission as our duty as christians who believe in God. Critical points are: Biblical understanding of missions in the life of a local church, practical actions as a local church that understands missions and desire to see people converted in the local church. 
', '', 'Albertus Pandya', NULL, NULL, NULL, 'Group 4', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(28, 'Reason to join a church', '2024-02-16 23:00:00+00', 'Billy Lugito', 'Kisah Para Rasul 2:42', 'If you want to be a healthy Christian, you need to be part of a healthy church. In this lesson, we will look at reasons to join a local church - a practice that is mandatory for Christians and has been the pattern for Christians since the first century.', '', 'Danny Kurniawan', NULL, NULL, NULL, 'Group 6', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(37, 'Keadilan Allah', '2024-04-05 22:00:00+00', 'Billy Lugito', 'Roma 3:1-8', 'Basic Principles of Faith: Exposition on Romans 3:1-8', '', 'Albertus Pandya', NULL, NULL, NULL, 'Group 1', 'bible_study', '', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
