	(92, 'Heroes of Faith', '2025-01-31 23:00:00+00', '-', 'Kejadian 22 : 1 - 19', 'Kepercayaan Abraham Diuji', 'Winston Alexander', 'Ido Manuel', '-', '-', '-', 'Group 1', 'bible_study', 'Winston Alexander', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
	(93, 'Heroes of Faith', '2025-02-07 23:00:00+00', 'Pdt. Titus Christanto', 'Kejadian 25 : 19 -34, 27 : 1 - 40', 'Yakub, si Pemegang Tumit', 'Jericho Oland Marsahala', 'Reggy Irawan', 'Victor Jordan', 'Danny Kurniawan', 'Group 4', 'Group 2', 'church_service', 'Victor Jordan', '2025-04-06 10:41:49.436374+00', '2025-04-06 10:41:49.456926+00'),
